test('state switches take effect for the next reading and each entry keeps a snapshot', () => {
  const m = make();
  const first = m.receive(pulse(128));
  m.setState({ aiWorks: false });
  const second = m.receive(pulse(128));
  assert.equal(first.dest, DEST.AI);
  assert.equal(second.dest, DEST.UNDECIDED);
  assert.equal(first.state.aiWorks, true);
  assert.equal(second.id, first.id + 1);
});

