test('women get the lab ranges for women where the lab gives them', () => {
  const women = Object.entries(INSPIRATION4.subjects).filter(([, s]) => s.sex === 'F');
  const men = Object.entries(INSPIRATION4.subjects).filter(([, s]) => s.sex === 'M');
  assert.ok(women.length > 0 && men.length > 0);
  const tp = Object.keys(women[0][1].panels)[0];
  const range = (panel) => Object.fromEntries(panel.map((a) => [a.code || a.name, `${a.min}-${a.max}`]));
  const f = range(women[0][1].panels[tp]);
  const mm = range(men[0][1].panels[tp]);
  const differ = Object.keys(f).filter((k) => k in mm && f[k] !== mm[k]);
  assert.ok(differ.length > 0, 'at least one analyte has a different range for women');
});

