test('each person has their own pile, history and pre-flight levels', () => {
  const m = make();
  m.receive(r('mood', 'bad', TOM));
  assert.equal(m.pendingReports(TOM), 1);
  assert.equal(m.pendingReports(ELLY), 0);
  assert.equal(m.review(ELLY).status, STATUS.EMPTY);
  assert.equal(m.pendingReports(TOM), 1, "Elly's review does not touch Tom's pile");
  m.receive(r('pulse', 72, TOM));
  m.receive(r('pulse', 80, TOM));
  assert.equal(m.history(TOM, 'pulse').length, 2);
  assert.equal(m.history(ELLY, 'pulse').length, 0);
  // The same result is in the norm for one person and out of it for another.
  assert.equal(m.receive(r('vo2max', 31, ELLY)).status, STATUS.OK); // Elly: above 80% of 38
  assert.equal(m.receive(r('vo2max', 31, TOM)).status, STATUS.OUT); // Tom: below 80% of 42
});

test('a reading can carry its own time, and history is kept in time order', () => {
  const m = make();
  const later = m.receive({ ...r('pulse', 90), time: '2026-03-02T08:00:00Z' });
  const earlier = m.receive({ ...r('pulse', 70), time: '2026-03-01T08:00:00Z' });
  assert.equal(later.time.toISOString(), '2026-03-02T08:00:00.000Z');
  assert.equal(earlier.person, TOM);
  const h = m.history(TOM, 'pulse');
  assert.deepEqual(h.map((x) => x.value), [70, 90]);
  assert.equal(m.receive({ ...r('pulse', 70), time: 'not a date' }).time.toISOString(), fixedNow().toISOString());
});

