// ---------- red limits: one reading past a published alarm value goes to the crew at once (drafts) ----------
const redOf = (e) => e.steps.find((s) => s.code === 'red-limit');

test('red limits: each measure at its published edge, with the right level', () => {
  const m = make();
  // [indicator, value, expected red level or null]
  const cases = [
    ['spo2', 93, null], ['spo2', 92, 'action'], ['spo2', 89, 'action'], ['spo2', 88, 'urgent'], // MedlinePlus
    ['bp', { sys: 180, dia: 100 }, null], ['bp', { sys: 181, dia: 100 }, 'urgent'], ['bp', { sys: 150, dia: 120 }, null], ['bp', { sys: 150, dia: 121 }, 'urgent'], // NHLBI
    ['bp', { sys: 89, dia: 60 }, 'action'], ['bp', { sys: 90, dia: 58 }, null], // NEWS2, started below 90 as a draft
    ['glucose', 70, null], ['glucose', 69, 'action'], ['glucose', 54, 'action'], ['glucose', 53, 'urgent'], // ADA levels 1 and 2
    ['temp', 37.9, null], ['temp', 38.0, 'action'], ['temp', 40.5, 'action'], ['temp', 40.6, 'urgent'], // CDC fever; MedlinePlus
    ['temp', 35.1, null], ['temp', 35.0, 'urgent'], ['temp', 34.9, 'urgent'], // NEWS2: a red 3 at 35.0 or less; MedlinePlus hypothermia: below 35
    ['pulse', 41, null], ['pulse', 40, 'urgent'], ['pulse', 130, null], ['pulse', 131, 'urgent'], // NEWS2 red values
    ['resp', 9, null], ['resp', 8, 'urgent'], ['resp', 24, null], ['resp', 25, 'urgent'], // NEWS2 red values
  ];
  for (const [indicator, value, level] of cases) {
    const name = `${indicator} ${JSON.stringify(value)}`;
    const e = m.receive(r(indicator, value));
    const red = redOf(e);
    assert.equal(red ? red.level : null, level, name);
    if (level) {
      assert.equal(e.status, STATUS.OUT, `${name} is outside the norm`);
      assert.equal(e.dest, DEST.CREW_ALARM, name);
    } else {
      assert.notEqual(e.dest, DEST.CREW_ALARM, name);
    }
  }
});

test('red limit: the automation alone, never the AI and never "undecided"; the doctor step follows the situation', () => {
  for (const [state, doctor] of [
    [{ aiWorks: true, doctorOnBoard: true, linkToEarth: true }, 'to-doctor-onboard'],
    [{ aiWorks: true, doctorOnBoard: false, linkToEarth: true }, 'to-doctor-earth'],
    [{ aiWorks: false, doctorOnBoard: false, linkToEarth: false }, 'doctor-queued'],
  ]) {
    const urgent = make(state).receive(r('spo2', 85));
    assert.equal(urgent.dest, DEST.CREW_ALARM, JSON.stringify(state));
    assert.deepEqual(codes(urgent), ['norm-used', 'out-of-norm', 'red-limit', 'alarm-person', 'alarm-crew', doctor]);
    assert.ok(urgent.steps.every((s) => s.by !== 'ai'), 'no AI on this path');
    const action = make(state).receive(r('glucose', 65));
    assert.deepEqual(codes(action), ['norm-used', 'out-of-norm', 'red-limit', 'alarm-person', 'alarm-cmo', doctor]);
  }
  const red = redOf(make({ aiWorks: false, linkToEarth: false }).receive(r('spo2', 85)));
  assert.equal(red.question, OPEN_QUESTION.DIRECT_ALARM);
  assert.equal(red.draft, true);
  assert.equal(red.limit.source, 'MedlinePlus (NIH)');
  assert.match(red.limit.url, /^https:\/\/medlineplus\.gov\//);
  // Outside the norm but not past a red limit, with the AI down: still the team's open question.
  assert.equal(make({ aiWorks: false }).receive(r('spo2', 94)).dest, DEST.UNDECIDED);
});

test('red limit: the crossed limit is kept in the history for the screen', () => {
  const m = make();
  m.receive(r('pulse', 72));
  m.receive(r('pulse', 180));
  const [calm, high] = m.history(TOM, 'pulse');
  assert.equal(calm.red, null);
  assert.equal(high.red.level, 'urgent');
  assert.equal(high.red.value, 131);
});

test('exercise: a reading marked as taken during exercise is recorded, not judged against a norm for rest', () => {
  const m = make();
  const hard = m.receive({ ...r('pulse', 150), context: 'exercise' });
  assert.equal(hard.status, STATUS.RECORDED);
  assert.equal(hard.dest, DEST.NONE);
  assert.deepEqual(codes(hard), ['exercise-recorded']);
  assert.equal(m.history(TOM, 'pulse')[0].context, 'exercise');
  assert.equal(m.receive({ ...r('resp', 30), context: 'exercise' }).status, STATUS.RECORDED);
  // A low limit holds at any time: 38 bpm during exercise still goes to the crew.
  assert.equal(redOf(m.receive({ ...r('pulse', 38), context: 'exercise' })).level, 'urgent');
  // Without the mark, 150 bpm is judged as a reading at rest.
  assert.equal(m.receive(r('pulse', 150)).dest, DEST.CREW_ALARM);
  // Blood pressure has no norm for rest marked, so the mark changes nothing there.
  assert.equal(m.receive({ ...r('bp', { sys: 200, dia: 100 }), context: 'exercise' }).dest, DEST.CREW_ALARM);
});

test("ship: a cabin value past the ship's own limit is the ship's alarm on every screen, with no doctor", () => {
  const ship = createMachine({ cells: CELLS, crew: [{ id: 'ship', baselines: {} }], state: { aiWorks: false, doctorOnBoard: false, linkToEarth: false }, now: fixedNow });
  const s = (indicator, value) => ship.receive({ person: 'ship', source: indicator, indicator, value });
  const depress = s('cabinPressure', 30);
  assert.equal(depress.dest, DEST.CREW_ALARM);
  assert.deepEqual(codes(depress), ['norm-used', 'out-of-norm', 'red-limit', 'ship-alarm']);
  assert.equal(redOf(depress).level, 'urgent');
  assert.equal(redOf(s('cabinO2', 121)).level, 'urgent');
  assert.equal(redOf(s('cabinO2', 357)).level, 'action');
  assert.equal(redOf(s('co2', 7.6)).level, 'action');
  // Outside the norm, inside the ship's limits: no ship alarm (here the AI is down, so it stays open).
  assert.equal(s('co2', 7.5).dest, DEST.UNDECIDED);
  assert.equal(s('cabinO2', 122).dest, DEST.UNDECIDED);
  assert.equal(s('cabinPressure', 34.5).status, STATUS.OK);
});

test('red limits in the config: complete, sourced, drafts, and always outside the norm', () => {
  const WHEN = ['below', 'atOrBelow', 'above', 'atOrAbove'];
  let count = 0;
  for (const cell of CELLS.filter((c) => c.red)) {
    for (const lim of cell.red) {
      count += 1;
      const name = `${cell.indicator} ${lim.when} ${lim.value}`;
      assert.ok(WHEN.includes(lim.when), name);
      assert.ok(Number.isFinite(lim.value), name);
      assert.ok(['action', 'urgent'].includes(lim.level), name);
      assert.ok(lim.source && /^https:\/\//.test(lim.url) && lim.note, `${name}: source, url and note`);
      assert.equal(lim.draft, true, `${name} is marked as a draft`);
      if (lim.url2) assert.ok(lim.source2 && /^https:\/\//.test(lim.url2), name);
      // A value just past the limit must be outside the cell's norm, or the alarm could fire inside the norm.
      const step = Number.isInteger(lim.value) ? 1 : 0.1;
      const past = lim.when === 'below' ? lim.value - step : lim.when === 'above' ? lim.value + step : lim.value;
      const value = cell.normType === 'below-both' ? { sys: 110, dia: 70, [lim.part]: past } : past;
      assert.equal(checkNorm(cell, value, CREW[0]).inNorm, false, `${name}: past the limit is outside the norm`);
      assert.ok(redLimitOf(cell, value), `${name}: crossed just past the limit`);
    }
  }
  assert.ok(count >= 15);
  assert.equal(redLimitOf({ red: [{ when: 'above', value: 1, level: 'urgent' }] }, 'abc'), null, 'an unreadable value crosses nothing');
});
